+++ b/scripts/check-stripe-endive.cjs
@@ -0,0 +1,13 @@
+const assert = require('node:assert');
+const fs = require('node:fs');
+const read = (p) => fs.readFileSync(p, 'utf8');
+assert.match(require('../node_modules/stripe/package.json').version, /^23\./);
+const server = read('lib/stripe.server.ts');
+const hook = read('app/api/webhooks/stripe/route.ts');
+const types = read('lib/stripe-types.ts');
+assert.ok(!server.includes('payment_method_types'));
+assert.ok(!server.includes('2025-06-30.basil') && !hook.includes('2025-06-30.basil'));
+assert.ok(server.includes('2026-09-30.endive') && hook.includes('2026-09-30.endive'));
+assert.ok(types.includes('items?.data?.[0]') && types.includes('current_period_end'));
+assert.ok(hook.includes('parent?.subscription_details'));
+console.log('ok');
